var canvas = GameObject.Find("Canvas_Lobby");
var graphics = canvas.GetComponentsInChildren<UnityEngine.UI.Graphic>(true);
var sb = new System.Text.StringBuilder();
sb.AppendLine($"Total Graphics in Canvas_Lobby: {graphics.Length}");
int blockingCount = 0;
foreach (var g in graphics) {
    if (g.raycastTarget) {
        var rt = g.rectTransform;
        // Check if it's large / full screen and not a button
        var btn = g.GetComponentInParent<UnityEngine.UI.Button>();
        if (btn == null && rt.rect.width > 800 && rt.rect.height > 600) {
            sb.AppendLine($"Potential blocking graphic: {g.gameObject.name} (type: {g.GetType().Name}, size: {rt.rect.width}x{rt.rect.height}, color: {g.color})");
            blockingCount++;
        }
    }
}
sb.AppendLine($"Total potential blocking full-screen graphics: {blockingCount}");
return sb.ToString();
